}
export declare function datePickerStateFactory<T, O extends DatePickerStateOptions<T>>({ getPlaceholderTime, mergeDateTime, setTimezone, getDateTime, useDateFieldState, adjustDateToFormat, }: DatePickerStateFactoryOptions<T, O>): (props: O) => DatePickerState<T>;
